code.source:
#include <iostream>
using namespace std;

int main() {
    int fish = 3;
    double price = 120.5;
    char grade = 'A';
    bool open_now = true;
    cout << "Fish: " << fish << endl;
    cout << "Price: " << price << endl;
    cout << "Grade: " << grade << endl;
    cout << "Open: " << open_now << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "int: " << sizeof(int) << endl;
    cout << "double: " << sizeof(double) << endl;
    cout << "char: " << sizeof(char) << endl;
    cout << "bool: " << sizeof(bool) << endl;
    return 0;
}

